using System.Data;
using System.IO;
using Microsoft.Data.Sqlite;
namespace Hisab;
public static class ReportingCompletenessTests
{
    public static void Run(string directory,List<string> results)
    {
        void Check(bool ok,string name){if(!ok)throw new Exception(name);results.Add("PASS "+name);}
        void Reject(Action action,string name){try{action();}catch(Exception ex) when(ex is InvalidOperationException or SqliteException){results.Add("PASS "+name);return;}throw new Exception(name);}
        using var s=new Store(Path.Combine(directory,"report-completeness-"+Guid.NewGuid()+".db"));var a=new AccountingService(s);var day=DateTime.Today.AddDays(-10);long cash=s.AccountId("1101"),equity=s.AccountId("3201");s.SaveAccount(null,"ASSET-RC","Equipment","Asset");s.SaveAccount(null,"LOAN-RC","Loan","Liability");long asset=s.AccountId("ASSET-RC"),loan=s.AccountId("LOAN-RC");
        long acquisition=a.Manual(day,"equipment partly financed",[new(asset,100000,0),new(cash,0,40000),new(loan,0,60000)]);a.SaveNoncashDisclosure(acquisition,asset,loan,"AssetAcquisition",60,"Financed portion only");
        Check(a.NoncashDisclosures(day,day).Single().Amount==60000&&a.CashMovements(day,day).Single().Amount==40000,"Noncash disclosure separates financed asset portion from cash payment");
        Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,loan,"AssetAcquisition",61,"too much"),"Noncash disclosure cannot exceed source credit amount");Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,cash,"OtherNoncash",1,"cash"),"Cash accounts cannot be used for noncash disclosure");Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,loan,"DebtToEquity",1,"wrong category"),"Noncash category must match journal accounts");Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,loan,"OtherNoncash",1,"duplicate allocation"),"Disclosure categories cannot double-allocate the same source balance");Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,loan,"AssetAcquisition",1.0001m,"precision"),"Noncash disclosure enforces three decimal precision");
        Check(a.NoncashDisclosures(day.AddDays(-1),day.AddDays(-1)).Count==0,"Noncash disclosures respect date cutoff");a.Reverse(acquisition,"cancel acquisition",day.AddDays(1));Check(a.NoncashDisclosures(day,day.AddDays(1)).Sum(r=>r.Amount)==0&&a.NoncashDisclosures(day.AddDays(1),day.AddDays(1)).Single().Amount==-60000,"Noncash reversal offsets original disclosure on reversal date");
        long conversion=a.Manual(day.AddDays(2),"convert loan",[new(loan,20000,0),new(equity,0,20000)]);a.SaveNoncashDisclosure(conversion,loan,equity,"DebtToEquity",20,"Debt conversion");Check(a.NoncashDisclosures(day.AddDays(2),day.AddDays(2)).Single().Category=="DebtToEquity","Debt conversion is disclosed without generating cash flow");
        long balance=s.Balance(equity);a.SaveNoncashDisclosure(conversion,loan,equity,"DebtToEquity",10,"Correct amount");Check(s.Balance(equity)==balance&&a.NoncashDisclosures(day.AddDays(2),day.AddDays(2)).Single().Amount==10000,"Disclosure correction changes presentation only");
        s.Exec("UPDATE entries SET debit=debit*2,credit=credit*2 WHERE doc=@p0",conversion);Check(a.NoncashDisclosures(day.AddDays(2),day.AddDays(2)).Single().Stale,"Changed source journal marks disclosure for review");a.SaveNoncashDisclosure(conversion,loan,equity,"DebtToEquity",0,"Remove stale disclosure");Check(a.NoncashDisclosures(day.AddDays(2),day.AddDays(2)).Count==0,"Explicit zero and reason remove a disclosure with audit history");
        var data=new DataTable();data.Columns.Add("الحساب / Account");data.Columns.Add("JOD");data.Rows.Add("نقدية, \"Cash\"\nsecond line","-1,234.567");data.Rows.Add("=SUM(A1:A2)","0.001");var captured=ReportSnapshot.Capture("trial","Trial at cutoff","Incomplete classification warning","Original company","ar","{\"to\":\"2026-11-24\"}",data);long id=s.SaveReportSnapshot(captured);
        data.Rows[0][1]="999.000";s.Set("company","Renamed company");s.SaveTranslations("accounts",cash,"اسم جديد","Renamed account");var loaded=s.LoadReportSnapshot(id);Check(loaded.Rows[0][1]=="-1,234.567"&&loaded.Company=="Original company"&&loaded.Language=="ar"&&loaded.Note.Contains("warning"),"Saved snapshot freezes values, company, language and warnings");
        Reject(()=>s.Exec("UPDATE report_snapshots SET title='changed' WHERE id=@p0",id),"Snapshot update is blocked at database level");Reject(()=>s.Exec("DELETE FROM report_snapshots WHERE id=@p0",id),"Snapshot deletion is blocked at database level");
        string csv=ReportCsv.Serialize(loaded.ToTable());using(var parser=new Microsoft.VisualBasic.FileIO.TextFieldParser(new StringReader(csv))){parser.SetDelimiters(",");parser.HasFieldsEnclosedInQuotes=true;parser.ReadFields();var first=parser.ReadFields()!;var second=parser.ReadFields()!;Check(first[0]==loaded.Rows[0][0]&&first[1]=="-1,234.567"&&second[0]=="'=SUM(A1:A2)"&&second[1]=="0.001","CSV roundtrip preserves Arabic, quotes, line breaks and JOD while escaping formulas");}
        Check(ReportCsv.SerializeSnapshot(loaded).Contains("Original company")&&ReportCsv.SerializeSnapshot(loaded).EndsWith(csv),"Snapshot CSV includes frozen metadata and identical table values");
        string backup=Path.Combine(directory,"snapshot-backup-"+Guid.NewGuid()+".db");s.Backup(backup);using(var restored=new Store(backup)){Check(restored.LoadReportSnapshot(id).Rows[0][1]=="-1,234.567"&&new AccountingService(restored).NoncashDisclosures(day,day).Single().Amount==60000,"Backup reopen preserves snapshots and noncash disclosures");}
        s.Exec("INSERT INTO report_snapshots(created,username,title,payload,hash) VALUES('test','test','bad','{}','bad')");long corrupt=Convert.ToInt64(s.Scalar("SELECT last_insert_rowid()"));Reject(()=>s.LoadReportSnapshot(corrupt),"Snapshot payload checksum detects corruption");
        s.SaveUser("report-viewer","TestPassword123","Viewer");s.Login("report-viewer","TestPassword123");Reject(()=>s.SaveReportSnapshot(captured),"Viewer cannot save report snapshots");Reject(()=>a.SaveNoncashDisclosure(acquisition,asset,loan,"AssetAcquisition",10,"viewer edit"),"Viewer cannot edit noncash disclosures");Check(s.LoadReportSnapshot(id).Company=="Original company","Viewer can read saved report snapshot");
    }
}
